use Zwii\Cms\Core; use Zwii\Cms\Helper; trait InputOutput { public function addRequiredInputNotices($key) { if (preg_match('#\[(.*)\]#', $key, $secondKey)) { $firstKey = explode('[', $key)[0]; $secondKey = $secondKey[1]; if (empty($this->input['_POST'][$firstKey][$secondKey])) { Core::$inputNotices[$firstKey . '_' . $secondKey] = Helper::translate('Obligatoire'); } } elseif (empty($this->input['_POST'][$key])) { Core::$inputNotices[$key] = Helper::translate('Obligatoire'); } } public function addOutput($output) { $this->output = array_merge($this->output, $output); } function secure_file_put_contents($filename, $data, $flags = 0) { if (empty($filename) || !is_string($filename)) { return false; } $dir = dirname($filename); if (!is_dir($dir) && !mkdir($dir, 0755, true)) { return false; } if (!is_writable($dir)) { return false; } $attempts = 0; $maxAttempts = self::FILE_WRITE_MAX_ATTEMPTS; while ($attempts < $maxAttempts) { $write_result = file_put_contents($filename, $data, LOCK_EX | $flags); if ($write_result !== false) { $read_data = file_get_contents($filename); if ($read_data === $data) { return true; } } $attempts++; usleep(self::FILE_WRITE_RETRY_DELAY * $attempts); } return false; } public function getInput($key, $filter = Helper::FILTER_STRING_SHORT, $required = false) { if (preg_match('#\[(.*)\]#', $key, $secondKey)) { $firstKey = explode('[', $key)[0]; $secondKey = $secondKey[1]; foreach ($this->input as $type => $values) { if ($required) { $this->addRequiredInputNotices($key); } if ( array_key_exists($firstKey, $values) and array_key_exists($secondKey, $values[$firstKey]) ) { if ($filter) { return Helper::filter($this->input[$type][$firstKey][$secondKey], $filter); } else { return $this->input[$type][$firstKey][$secondKey]; } } } } else { foreach ($this->input as $type => $values) { if ($required) { $this->addRequiredInputNotices($key); } if (array_key_exists($key, $values)) { if ($filter) { return Helper::filter($this->input[$type][$key], $filter); } else { return $this->input[$type][$key]; } } } } return Helper::filter(null, $filter); } public function isPost() { if ($this->checkCSRF() === false || $this->input['_POST'] === []) { return false; } $currentInstance = $this->getCurrentModuleInstanceId(); if ( $currentInstance !== '' && array_key_exists('moduleInstanceId', $this->input['_POST']) ) { $postedInstance = $this->input['_POST']['moduleInstanceId']; if ( !is_string($postedInstance) || $postedInstance === '' || $postedInstance !== $currentInstance ) { return false; } } return true; } public function sendMail($to, $subject, $content, $replyTo = null, $serverEmail = null, $file_name = null) { $serverName = $this->getData(['locale', 'title']) ?: 'Site'; $serverDomain = parse_url(Helper::baseUrl(false), PHP_URL_HOST) ?: ($_SERVER['SERVER_NAME'] ?? 'localhost'); if (empty($to) || empty($subject) || empty($content)) { $this->saveLog('Échec sendMail : paramètres manquants.', true); return 'Paramètres manquants'; } if (!$serverEmail || !filter_var($serverEmail, FILTER_VALIDATE_EMAIL)) { $this->saveLog('Échec sendMail : adresse expéditeur invalide ou absente.', true); return 'Adresse expéditeur invalide'; } $layoutFile = 'core/layout/mail.php'; if (is_file($layoutFile)) { ob_start(); include $layoutFile; $layout = ob_get_clean(); } else { $this->saveLog('Layout mail introuvable : ' . $layoutFile, true); $layout = $content; } $mail = new \PHPMailer\PHPMailer\PHPMailer(true); $mail->CharSet = 'UTF-8'; $mail->Hostname = $serverDomain ?: (gethostname() ?: 'localhost'); try { $smtpEnabled = filter_var($this->getData(['config', 'smtp', 'enable']), FILTER_VALIDATE_BOOLEAN); if ($smtpEnabled) { $mail->isSMTP(); $mail->Host = $this->getData(['config', 'smtp', 'host']); $mail->Port = (int) $this->getData(['config', 'smtp', 'port']); $mail->SMTPAuth = filter_var($this->getData(['config', 'smtp', 'auth']), FILTER_VALIDATE_BOOLEAN); $secure = strtolower((string) $this->getData(['config', 'smtp', 'secure'])); $mail->SMTPSecure = in_array($secure, ['ssl', 'tls'], true) ? $secure : ''; $mail->SMTPAutoTLS = ($mail->SMTPSecure === 'tls'); if ($mail->SMTPAuth) { $mail->Username = $this->getData(['config', 'smtp', 'username']); $mail->Password = Helper::decrypt( $this->getData(['config', 'smtp', 'password']), $mail->Host ); } $mail->Sender = $serverEmail; } else { $mail->isMail(); $senderHost = strtolower(preg_replace('#^www\.#', '', (string) substr(strrchr($serverEmail, '@'), 1))); $siteHost = strtolower(preg_replace('#^www\.#', '', (string) $serverDomain)); if ($senderHost !== '' && $siteHost !== '' && $senderHost === $siteHost) { $mail->Sender = $serverEmail; } else { $this->saveLog( 'mail() : hôte expéditeur (' . $senderHost . ') différent du site (' . $siteHost . '), -f non forcé.', true ); } } $mail->setFrom($serverEmail, $serverName); $mail->addReplyTo($replyTo ?: $serverEmail, $serverName); $recipients = is_array($to) ? $to : explode(',', $to); $validCount = 0; foreach ($recipients as $email) { $email = trim($email); if (filter_var($email, FILTER_VALIDATE_EMAIL)) { $mail->addAddress($email); $validCount++; } } if ($validCount === 0) { $this->saveLog('Échec sendMail : aucun destinataire valide.', true); return 'Aucun destinataire valide'; } $mail->isHTML(true); $mail->Subject = $subject; $mail->Body = $layout; $mail->AltBody = strip_tags($content); $mail->addCustomHeader('List-Unsubscribe', '<mailto:' . $serverEmail . '?subject=unsubscribe>'); $mail->XMailer = ' '; if (!empty($file_name)) { $filePath = self::FILE_DIR . 'uploads/' . basename($file_name); if (is_file($filePath)) { $mail->addAttachment($filePath); } } $sent = $mail->send(); if (!$sent) { $error = $mail->ErrorInfo !== '' ? $mail->ErrorInfo : 'Erreur inconnue'; $this->saveLog('Échec envoi mail : ' . $error, true); return $error; } if (!$smtpEnabled) { $this->saveLog('mail() : message remis au MTA local (livraison non garantie).', true); } return true; } catch (\PHPMailer\PHPMailer\Exception $e) { $error = $mail->ErrorInfo !== '' ? $mail->ErrorInfo : $e->getMessage(); $this->saveLog('Erreur PHPMailer : ' . $error, true); return $error; } catch (\Throwable $e) { $this->saveLog('Erreur sendMail : ' . $e->getMessage(), true); return $e->getMessage(); } } protected function getCorrectedSmtpFrom($smtpFrom) { if (empty($smtpFrom) || !filter_var($smtpFrom, FILTER_VALIDATE_EMAIL)) { return $smtpFrom; } $baseUrl = Helper::baseUrl(false); $parsedUrl = parse_url($baseUrl); $hostname = isset($parsedUrl['host']) ? $parsedUrl['host'] : (isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : ''); if (empty($hostname)) { return $smtpFrom; } $hostname = strtolower($hostname); $hostname = preg_replace('#^www\.#', '', $hostname); $siteDomain = $hostname; $emailParts = explode('@', $smtpFrom); if (count($emailParts) !== 2) { return $smtpFrom; } $localPart = $emailParts[0]; $emailDomain = strtolower($emailParts[1]); if ( ($emailDomain === 'localhost' || strpos($emailDomain, '127.0.0.1') !== false) && ($siteDomain !== 'localhost' && strpos($siteDomain, '127.0.0.1') === false) ) { return $localPart . '@' . $siteDomain; } if ( strcasecmp($emailDomain, $siteDomain) === 0 || strcasecmp($emailDomain, 'www.' . $siteDomain) === 0 ) { return $smtpFrom; } return $localPart . '@' . $siteDomain; } public function saveLog($message = '', $force = false) { $logFile = self::DATA_DIR . 'journal.log'; if (file_exists($logFile) && filesize($logFile) > self::getCoreParam('logMaxsize', self::LOG_MAXSIZE)) { $this->rotateLogFile(); } $dataLog = Helper::dateUTF8('%Y%m%d', time(), self::$i18nUI) . ';' . Helper::dateUTF8('%H:%M', time(), self::$i18nUI) . ';'; $dataLog .= Helper::getIp($this->getData(['config', 'connect', 'anonymousIp'])) . ';'; $dataLog .= empty($this->getUser('id')) ? 'visitor;' : $this->getUser('id') . ';'; $dataLog .= $message ? $this->getUrl() . ';' . $message : $this->getUrl(); $dataLog .= PHP_EOL; if ( $this->getData(['config', 'connect', 'log']) || $force ) { file_put_contents($logFile, $dataLog, FILE_APPEND); } } private function rotateLogFile(): bool { $logFile = self::DATA_DIR . 'journal.log'; if (!is_readable($logFile) || !is_writable(dirname($logFile))) { trigger_error('Fichier journal inaccessible ou dossier non inscriptible', E_USER_WARNING); return false; } if (filesize($logFile) < 1024) { return true; } $lockFile = fopen($logFile, 'r'); if (!flock($lockFile, LOCK_EX | LOCK_NB)) { fclose($lockFile); trigger_error('Fichier journal déjà utilisé par un autre processus', E_USER_WARNING); return false; } $tempFile = null; try { for ($i = self::getCoreParam('logMaxarchive', self::LOG_MAXARCHIVE) - 1; $i > 0; $i--) { $oldFile = self::DATA_DIR . 'journal-' . $i . '.log.gz'; $newFile = self::DATA_DIR . 'journal-' . ($i + 1) . '.log.gz'; if (file_exists($oldFile)) { if ($i >= self::getCoreParam('logMaxarchive', self::LOG_MAXARCHIVE) - 1) { if (!unlink($oldFile)) { trigger_error('Impossible de supprimer l\'ancienne archive: ' . $oldFile, E_USER_WARNING); } } else if (!rename($oldFile, $newFile)) { trigger_error(sprintf('Échec du déplacement de %s vers %s', $oldFile, $newFile), E_USER_WARNING); } } } $tempFile = tempnam(sys_get_temp_dir(), 'zwii_log_'); if (!copy($logFile, $tempFile)) { throw new \RuntimeException('Échec de la copie temporaire du journal'); } $gzFile = self::DATA_DIR . 'journal-1.log.gz'; $gz = @gzopen($gzFile, 'w9'); if ($gz === false) { throw new \RuntimeException('Impossible d\'ouvrir le fichier de destination pour la compression'); } $source = fopen($tempFile, 'r'); if ($source === false) { gzclose($gz); throw new \RuntimeException('Impossible de lire le fichier source pour la compression'); } stream_copy_to_stream($source, $gz); fclose($source); gzclose($gz); if (!file_exists($gzFile) || filesize($gzFile) === 0) { throw new \RuntimeException('La compression du journal a échoué'); } if (file_put_contents($logFile, '') === false) { throw new \RuntimeException('Impossible de vider le fichier journal'); } @unlink($tempFile); $tempFile = null; flock($lockFile, LOCK_UN); fclose($lockFile); return true; } catch (\Exception $e) { if ($tempFile) { @unlink($tempFile); } if (isset($lockFile)) { flock($lockFile, LOCK_UN); fclose($lockFile); } trigger_error('Erreur lors de la rotation du journal: ' . $e->getMessage(), E_USER_WARNING); return false; } } }
